import openpyxl
from pprint import pprint

path='/root/nasa_budget_incomplete.xlsx'
wb=openpyxl.load_workbook(path, data_only=False)

def dump_sheet(ws, max_row=None, max_col=None):
    if max_row is None:
        max_row=ws.max_row
    if max_col is None:
        max_col=ws.max_column
    data=[]
    for r in range(1, max_row+1):
        row=[]
        for c in range(1, max_col+1):
            v=ws.cell(r,c).value
            row.append(v)
        data.append(row)
    return data

for name in wb.sheetnames:
    ws=wb[name]
    print('\n==', name, '==')
    data=dump_sheet(ws)
    for row in data:
        print(row)
